// Get inputs passed into this sub-workflow
const triggerInput = $('When Executed by Another Workflow').first().json;
const memberId = triggerInput.member_id ?? null;
const serviceCode = triggerInput.service_code ?? null;
const serviceDate = triggerInput.service_date ?? null;

// Parsed authorizations.json from the previous node
const authorizations = $input.first().json.data;

// Validate input
if (!memberId || !serviceCode || !serviceDate) {
  return [
    {
      json: {
        tool: 'AUTHORIZATION',
        status: 'INVALID_INPUT',
        member_id: memberId,
        service_code: serviceCode,
        service_date: serviceDate,
        data: null,
        error: 'member_id, service_code and service_date are required'
      }
    }
  ];
}

// Dates are normalized YYYY-MM-DD, so direct comparison is deterministic
const authorization = authorizations.find(
  (record) =>
    record.member_id === memberId &&
    record.service?.service_code === serviceCode &&
    (!record.effective_start_date ||
      serviceDate >= record.effective_start_date) &&
    (!record.effective_end_date ||
      serviceDate <= record.effective_end_date)
);

// Authorization not found
if (!authorization) {
  return [
    {
      json: {
        tool: 'AUTHORIZATION',
        status: 'NOT_FOUND',
        member_id: memberId,
        service_code: serviceCode,
        service_date: serviceDate,
        data: null,
        error: 'Authorization not found'
      }
    }
  ];
}

// Return only fields useful to servicing
return [
  {
    json: {
      tool: 'AUTHORIZATION',
      status: 'SUCCESS',
      member_id: authorization.member_id,
      service_code: authorization.service.service_code,
      service_date: serviceDate,
      data: {
        authorization_id: authorization.authorization_id,
        service_name: authorization.service.service_name,
        status: authorization.status,
        provider_id: authorization.provider_id,
        provider_location_id:
          authorization.provider_location_id,
        effective_start_date:
          authorization.effective_start_date ?? null,
        effective_end_date:
          authorization.effective_end_date ?? null
      },
      error: null
    }
  }
];
